tool_context:
{
  "toolConfig": {
    "tools": [
      {
        "toolSpec": {
          "name": "document_analysis_extraction",
          "description": "Analyze a document and extract structured information including title, organization, geography, tags with source indicators, reasons and descriptions, summary, document type with reasoning, key entities, and structured content for templates with proper formatting preservation.",
          "inputSchema": {
            "json": {
              "type": "object",
              "properties": {
                "title": {
                  "type": "string",
                  "description": "For templates: SMART PATTERN MATCHING - Look for any section/heading containing 'Title' (case-insensitive): 'Solution Title:', 'Asset Title:', '1. Asset Title', '2. Solution Title', etc. Extract value from same line (after colon) or next line. Handle both formats flexibly regardless of punctuation or numbering. FALLBACK: extract from document header only if no title field found. For non-templates: create descriptive title or extract from title field if present. Clean up formatting issues, remove duplicate words, convert ALL CAPS to Title Case. Avoid questions as titles."
                },
                "title_reason": {
                  "type": "string",
                  "description": "Explanation for why this title was selected. For title fields found: 'Extracted from [specific field name] field in document' (e.g., 'Extracted from Solution Title field in document', 'Extracted from 1. Asset Title section in document'). For fallback cases: 'No title field found, extracted from document header' or 'No title field found, created descriptive title from document content'."
                },
                "organization": {
                  "type": "string",
                  "description": "Organization or company name explicitly mentioned in the document (if any)"
                },
                "geography": {
                  "type": "string",
                  "description": "Geographic location if mentioned in the document (e.g., from 'Geography: Chennai', location fields, or specific geographic references in content). Empty string if no geographic information found."
                },
                "tags": {
                  "type": "array",
                  "items": {
                    "type": "object",
                    "properties": {
                      "text": {
                        "type": "string",
                        "description": "Tag text from the master tag list only"
                      },
                      "source": {
                        "type": "string",
                        "enum": [
                          "extracted"
                        ],
                        "description": "Always 'extracted' - either from explicit tags section or from content analysis matching master list"
                      },
                      "reason": {
                        "type": "string",
                        "description": "For explicit tags: 'Explicitly listed in document's tags/keywords section'. For content-based: 'Matches document's focus on [specific topic]'"
                      },
                      "description": {
                        "type": "string",
                        "description": "Always empty string '' for extracted tags"
                      }
                    },
                    "required": [
                      "text",
                      "source",
                      "reason",
                      "description"
                    ]
                  },
                  "description": "Tags strictly from the provided master tag list. Extract from explicit tags section if present, otherwise select relevant tags from master list that match document content. Empty array if no relevant tags exist."
                },
                "summary": {
                  "type": "string",
                  "description": "Comprehensive summary of approximately 200 words. Structure: what the document is → main components/approach → goals/impact. Be specific, avoid vagueness or repeating title information."
                },
                "document_type": {
                  "type": "object",
                  "properties": {
                    "type": {
                      "type": "string",
                      "description": "Document type selected strictly from the master document type list. Only use 'template' if title explicitly contains 'template'. Empty string if no match found."
                    },
                    "reason": {
                      "type": "string",
                      "description": "Explanation for why this document type was selected based on observable document characteristics (structure, purpose, format). Reference specific document features."
                    }
                  },
                  "required": ["type", "reason"],
                  "description": "Document type from master list with reasoning. Template rule: only classify as 'template' if title contains 'template'."
                },
                "key_entities": {
                  "type": "array",
                  "items": {
                    "type": "string"
                  },
                  "description": "ONLY proper names of people and specific locations mentioned in the document. Do NOT include organizations (already in 'organization' field) or concepts/terms (already in 'tags'). Example: ['Dr. Jane Smith', 'Seattle', 'Building A']"
                },
                "structured_content": {
                  "type": "object",
                  "additionalProperties": {
                    "oneOf": [
                      {
                        "type": "string",
                        "description": "For paragraph content only - single string with preserved text formatting"
                      },
                      {
                        "type": "array",
                        "items": {
                          "type": "string"
                        },
                        "description": "For bullet/list content or mixed content - array where first item can be paragraph text followed by bullet points, all as separate strings with cleaned text (no bullet markers)"
                      }
                    ]
                  },
                  "description": "For template documents only: heading-content pairs with simplified formatting. Detect content type and format accordingly: bullets/lists as arrays, paragraphs as strings, mixed content as arrays with paragraph text as first item followed by bullet points. Clean heading keys (remove numbers/bullets/special chars). EXCLUDES: 'Basic Information', 'General Information', 'Tags', 'Keywords', 'Categories', 'Classification', 'Tags for Classification'. NO nested objects with 'description' and 'key_points' structures allowed."
                }
              },
              "required": [
                "title",
                "title_reason",
                "organization", 
                "geography",
                "tags",
                "summary",
                "document_type",
                "key_entities"
              ]
            }
          }
        }
      }
    ]
  }
}
